function moveHorizontal(p, axis, dt) {
  const speed = 260;
  const accel = 1450;
  const target = Math.max(-1, Math.min(1, axis)) * speed;
  const diff = Math.max(-accel * dt, Math.min(accel * dt, target - p.vx));
  p.vx += diff;
  p.x += p.vx * dt;
  if (Math.abs(p.vx) > 0.1) p.facing = Math.sign(p.vx);
  return p;
}

function jumpAndGravity(p, jump, dt, floorY) {
  if (jump && p.grounded) {
    p.vy = -620;
    p.grounded = false;
  }
  p.vy = Math.min(980, p.vy + 1700 * dt);
  p.y += p.vy * dt;
  if (p.y >= floorY && p.vy >= 0) {
    p.y = floorY;
    p.vy = 0;
    p.grounded = true;
  }
  return p;
}

function advanceCombo(state, attackPressed, now) {
  if (now > state.windowEnd) state.chain = 0;
  if (attackPressed && now >= state.nextReady) {
    state.chain = Math.min(3, state.chain + 1);
    state.nextReady = now + 0.2;
    state.windowEnd = now + 0.7;
    return state.chain;
  }
  return 0;
}

function applyHit(target, amount, direction, now) {
  if (target.hp <= 0 || now < target.invulnerableUntil) return false;
  target.hp = Math.max(0, target.hp - Math.max(0, amount));
  target.vx = Math.sign(direction || 1) * 280;
  target.vy = -160;
  target.invulnerableUntil = now + 0.35;
  return true;
}

function hitboxesOverlap(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x &&
         a.y < b.y + b.h && a.y + a.h > b.y;
}

function patrolEnemy(enemy, left, right, dt) {
  if (enemy.x >= right) enemy.direction = -1;
  if (enemy.x <= left) enemy.direction = 1;
  enemy.x = Math.max(left, Math.min(right, enemy.x + enemy.direction * 68 * dt));
  return enemy;
}

extends CharacterBody2D
@export var left_bound = 100.0
@export var right_bound = 400.0
var direction = 1.0
func _physics_process(delta: float) -> void:
    if global_position.x >= right_bound:
        direction = -1.0
    if global_position.x <= left_bound:
        direction = 1.0
    velocity.x = direction * 70.0
    velocity.y += 1200.0 * delta
    move_and_slide()
